const asPaymentStatus = (
  value: string,
): LeaseDetail["payments"][number]["status"] => {
  const status = paymentStatuses.find((s) => s === value);
  if (!status) {
    throw new Error(`Unknown payment status in database: ${value}`);
  }
  return status;
