  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { MANUAL_PAYMENT_METHODS, type ManualPaymentMethod } from "@/lib/enums";
import { useRecordPaymentForm } from "./use-record-payment-form";

